  RFLObstructionBuilder builder_(_fbb);
  builder_.add_DISTANCE_FROM_TRANSMITTER_M(DISTANCE_FROM_TRANSMITTER_M);
  builder_.add_FRESNEL_CLEARANCE_FRACTION(FRESNEL_CLEARANCE_FRACTION);
  builder_.add_EXCESS_DELAY_S(EXCESS_DELAY_S);
  builder_.add_LOSS_DB(LOSS_DB);
  builder_.add_PATH_LENGTH_IN_MATERIAL_M(PATH_LENGTH_IN_MATERIAL_M);
  builder_.add_INCIDENCE_ANGLE_DEG(INCIDENCE_ANGLE_DEG);
  builder_.add_NORAD_CAT_ID(NORAD_CAT_ID);
  builder_.add_VARIANT_ID(VARIANT_ID);
  builder_.add_VAM_ID(VAM_ID);
  builder_.add_GEOMETRY_REF_ID(GEOMETRY_REF_ID);
  builder_.add_MATERIAL_ID(MATERIAL_ID);
  builder_.add_OBSTACLE_ID(OBSTACLE_ID);
