  auto RFE_ID__ = RFE_ID ? _fbb.CreateString(RFE_ID) : 0;
  auto IQC_ID__ = IQC_ID ? _fbb.CreateString(IQC_ID) : 0;
  auto ID_BEAM__ = ID_BEAM ? _fbb.CreateString(ID_BEAM) : 0;
  auto CHANNEL_ID__ = CHANNEL_ID ? _fbb.CreateString(CHANNEL_ID) : 0;
