inline const RFL *GetRFL(const void *buf) {
  return ::flatbuffers::GetRoot<RFL>(buf);
}

inline const RFL *GetSizePrefixedRFL(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<RFL>(buf);
}

inline const char *RFLIdentifier() {
  return "$RFL";
}

inline bool RFLBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, RFLIdentifier());
}

inline bool SizePrefixedRFLBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, RFLIdentifier(), true);
}

template <bool B = false>
inline bool VerifyRFLBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<RFL>(RFLIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedRFLBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<RFL>(RFLIdentifier());
}

inline void FinishRFLBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<RFL> root) {
  fbb.Finish(root, RFLIdentifier());
}

inline void FinishSizePrefixedRFLBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<RFL> root) {
  fbb.FinishSizePrefixed(root, RFLIdentifier());
}

